/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isSymbolArray = require( '@stdlib/plot/base/assert/is-symbol-array' );
var isSymbol = require( '@stdlib/plot/base/assert/is-symbol' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var symbols2shapes = require( '@stdlib/plot/base/symbols2shapes' );
var format = require( '@stdlib/string/format' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'scatterplot:set:'+prop.name );


// MAIN //

/**
* Sets symbols.
*
* @private
* @param {(Array<string>|string)} value - input value
* @throws {TypeError} must be a string or an array of strings
* @returns {void}
*/
function set( value ) {
	var isStr = isSymbol( value );
	if ( !isStr && !isSymbolArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a symbol or an array of symbols. Value: `%s`.', prop.name, value ) );
	}
	if ( isStr ) {
		value = [ value ];
	}
	if ( !hasEqualValues( value, this[ prop.private ] ) ) {
		debug( 'Current value: [%s]. New value: [%s].', join( this[ prop.private ], ', ' ), join( value, ', ' ) );

		// Perform a defensive copy as we will be caching the specified symbols:
		value = copy( value );

		// Cache the value before updating the scale to ensure consistent state:
		this[ prop.private ] = value;

		// Convert the symbols to symbol mark shapes:
		this.symbolsScale.range = symbols2shapes( value );
	}
}


// EXPORTS //

module.exports = set;
